{"action":"write_file","path":"controller.js","content":"function act(o,m){
  const W=o.width,H=o.height,N=W*H,me=o.courier, jobs=o.jobs;
  m=m||{seen:{}};
  for(const e of o.enemies)m.seen[e.id]={x:e.x,y:e.y,t:o.tick,kind:e.kind,period:e.period};
  const id=(x,y)=>y*W+x, xy=i=>[i%W,(i/W)|0];
  const pass=i=>{let [x,y]=xy(i);return x>=0&&y>=0&&x<W&&y<H&&o.map[y][x]!='#'};
  const dirs=[[0,-1,'N'],[1,0,'E'],[0,1,'S'],[-1,0,'W']];
  const here=id(me.x,me.y), cargo=new Set(me.cargo);
  const distFrom=(start)=>{let d=new Int16Array(N);d.fill(-1);let q=new Int16Array(N),a=0,b=0;q[b++]=start;d[start]=0;while(a<b){let v=q[a++],[x,y]=xy(v);for(const z of dirs){let u=id(x+z[0],y+z[1]);if(pass(u)&&d[u]<0){d[u]=d[v]+1;q[b++]=u}}}return d};
  const dh=distFrom(here);
  // Complete actions at the current square before choosing a route.
  let deliver=false;
  for(const j of jobs)if(cargo.has(j.id)&&j.to.x==me.x&&j.to.y==me.y&&o.tick<=j.deadline)deliver=true;
  if(deliver)return {action:{type:'deliver'},memory:m};
  let used=0;for(const j of jobs)if(cargo.has(j.id))used+=j.weight;
  for(const j of jobs)if(j.status=='available'&&j.from.x==me.x&&j.from.y==me.y&&used+j.weight<=o.cargoCapacity)return {action:{type:'pickup',id:j.id},memory:m};
  // Beam search over pickup/delivery events.  Static grid distance is deliberately used here;
  // movement below supplies the tactical detour around robots.
  const pos=[here];for(const j of jobs){pos.push(id(j.from.x,j.from.y),id(j.to.x,j.to.y))}
  const dd=[];for(let i=0;i<pos.length;i++)dd[i]=distFrom(pos[i]);
  let initMask=0,avail=0;for(let i=0;i<jobs.length;i++){if(cargo.has(jobs[i].id))initMask|=1<<i;else if(jobs[i].status=='available')avail|=1<<i}
  let beam=[{p:0,c:initMask,a:avail,t:o.tick,val:0,first:-1}];let best=null;
  for(let depth=0;depth<10&&beam.length;depth++){
    let next=[];
    for(const s of beam){let wt=0;for(let i=0;i<jobs.length;i++)if(s.c>>i&1)wt+=jobs[i].weight;
      for(let i=0;i<jobs.length;i++){let bit=1<<i,j=jobs[i];
        if((s.c&bit)){let np=2+i*2,dt=dd[s.p][pos[np]];if(dt<0)continue;let nt=s.t+dt;if(nt>j.deadline)continue;let v=s.val+j.value;let z={p:np,c:s.c&~bit,a:s.a,t:nt,val:v,first:s.first<0?np:s.first};next.push(z);if(!best||v*100000-nt>best.val*100000-best.t)best=z}
        else if((s.a&bit)&&wt+j.weight<=o.cargoCapacity){let np=1+i*2,dt=dd[s.p][pos[np]];if(dt<0)continue;next.push({p:np,c:s.c|bit,a:s.a&~bit,t:s.t+dt,val:s.val,first:s.first<0?np:s.first})}
      }
    }
    next.sort((u,v)=>(v.val*10000-v.t)-(u.val*10000-u.t));
    let uniq=new Map;beam=[];for(const s of next){let k=s.p+','+s.c+','+s.a;if(!uniq.has(k)){uniq.set(k,1);beam.push(s);if(beam.length>=100)break}}
  }
  let target=best&&best.first>=0?pos[best.first]:-1;
  // If no useful delivery sequence remains, wait safely.
  if(target<0)return {action:{type:'wait'},memory:m};
  // Reserve enough power to get to the target and then to a charger.  Heavy cargo costs 2/cell.
  let near=1e4;for(const c of o.chargers){let q=id(c.x,c.y),d=dd[0][q];if(d>=0&&d<near)near=d}
  let after=1e4;for(const c of o.chargers){let q=id(c.x,c.y),d=distFrom(target)[q];if(d>=0&&d<after)after=d}
  let stepCost=used>3?2:1;
  if(me.battery<=stepCost*(dh[target]+after)+5){let bc=-1,bd=1e4;for(const c of o.chargers){let q=id(c.x,c.y);if(dh[q]>=0&&dh[q]<bd){bd=dh[q];bc=q}}target=bc}
  if(target==here){if(o.chargers.some(c=>c.x==me.x&&c.y==me.y)&&me.battery<90)return {action:{type:'charge'},memory:m};return {action:{type:'wait'},memory:m}}
  // Reverse BFS with visible robots and their immediate neighborhoods as hazards.
  function route(strict){let d=new Int16Array(N);d.fill(-1);let q=new Int16Array(N),a=0,b=0;q[b++]=target;d[target]=0;while(a<b){let v=q[a++],[x,y]=xy(v);for(const z of dirs){let u=id(x+z[0],y+z[1]);if(!pass(u)||d[u]>=0)continue;let bad=false;for(const k in m.seen){let e=m.seen[k],age=o.tick-e.t;if(age> (strict?4:0))continue;let [ux,uy]=xy(u),md=Math.abs(ux-e.x)+Math.abs(uy-e.y);if(md==0||(strict&&md<=1))bad=true}if(!bad){d[u]=d[v]+1;q[b++]=u}}}return d}
  let rd=route(true);let choices=[];for(const z of dirs){let x=me.x+z[0],y=me.y+z[1],u=id(x,y);if(pass(u)&&rd[u]>=0)choices.push([rd[u],z])}if(!choices.length){rd=route(false);for(const z of dirs){let u=id(me.x+z[0],me.y+z[1]);if(pass(u)&&rd[u]>=0)choices.push([rd[u],z])}}
  if(!choices.length)return {action:{type:'wait'},memory:m};
  choices.sort((a,b)=>a[0]-b[0]);return {action:{type:'move',dir:choices[0][1][2]},memory:m};
}
module.exports={act};"}

